    if mibBuilder.loadTexts: ciscoPowerEthernetExtMIB.setRevisionsDescriptions(('Added following OBJECT-GROUP\n        - cpeExtPseInfoPwrGroup\n        Added new compliance\n        - cpeExtMIBCompliance6.', 'Added following TEXTUAL-CONVENTION\n        - CpeExtLldpPwrClassOrZero\n        Added following OBJECT-GROUP\n        - cpeExtPsePortLldpPowerGroup\n        Added new compliance\n        - cpeExtMIBCompliance5.', "Added cpeExtPowerPriorityGroup, cpeExtPsePortLldpGroup\n        and cpeExtPsePortCapabilitiesGroup.\n\n        Added a new enumeration 'class4' in cpeExtPdStatsClass.\n\n        Added TEXTUAL-CONVENTION CpeExtLldpPwrType,\n        CpeExtLldpPwrSrc, and CpeExtPwrPriority.", 'Updated the DESCRIPTION of cpeExtPolicingNotif.', "Added 'overdrawLog' value to cpeExtPsePortAdditionalStatus.\n        Added cpeExtPortPolicingActionGroup, cpeExtPortPwrManAllocGroup\n        cpeExtPolicingNotifEnableGroup, and cpeExtPolicingNotifGroup.", 'Added cpeExtPsePortEntPhyIndex,\n        cpeExtPsePortPolicingCapable and \n        cpeExtPsePortPolicingEnable to cpeExtPsePortTable.\n        Added cpeExtPdStatsTotalDevices and cpeExtPdStatsTable.\n        Added enumerated value disable(5) to cpeExtPsePortEnable.', "Added 'limit' to cpeExtPsePortEnable, 'overdraw' to\n        cpeExtPsePortAdditionalStatus and the groups\n        cpeExtPsePortPwrMonitorGroup and\n        cpeExtMainPseGroup.", 'Initial version of this MIB module.',))
